--- skills.entries ---
{}
--- plugins ---
{
  "entries": {
    "minimax": {
      "enabled": true,
      "config": {}
    }
  }
}
--- agents ---
{
  "defaults": {
    "model": {
      "primary": "custom-001/deepseek-v4-flash",
      "fallbacks": [
        "minimax/MiniMax-M2.7",
        "minimax-portal/MiniMax-M2.7-highspeed",
        "openrouter/auto",
        "deepseek/deepseek-chat",
        "xiaomi/mimo-v2-flash"
      ]
    },
    "models": {
      "minimax-portal/MiniMax-M2.7": {
        "alias": "minimax-m2.7"
      },
      "minimax/MiniMax-M2.7": {
        "alias": "Minimax"
      },
      "minimax-portal/MiniMax-M2.7-highspeed": {
        "alias": "minimax-m2.7-highspeed"
      },
      "openrouter/auto": {
        "alias": "OpenRouter"
      },
      "deepseek/deepseek-chat": {
        "alias": "DeepSeek"
      },
      "xiaomi/mimo-v2-flash": {
        "alias": "Xiaomi"
      },
      "custom-001/deepseek-v4-flash": {
        "alias": "deepseek-v4-flash"
      },
      "deepseek-v4-flash/deepseek-v4-flash": {
        "alias": "deepseek-v4-flash-old"
      }
    },
    "contextPruning": {
      "mode": "cache-ttl",
      "ttl": "1h"
    },
    "compaction": {
      "mode": "safeguard"
    },
    "heartbeat": {
      "every": "30m"
    },
    "maxConcurrent": 4,
    "subagents": {
      "maxConcurrent": 8,
