# Click on 房源 (Houses) in the left menu using JS via CDP
node -e "
const WebSocket = require('ws');
const ws = new WebSocket('ws://localhost:9222/devtools/page/ECB06F2BC4693849323A2A64BAD928C4');

ws.on('open', () => {
  const cmd = {
    id: 1,
    method: 'Runtime.evaluate',
    params: {
      expression: \`
        (function() {
          // Find all elements and look for 房源 text
          const allElements = document.querySelectorAll('*');
          for (const el of allElements) {
            if (el.textContent.trim() === '房源' && el.offsetParent !== null) {
              el.click();
              return 'Clicked: 房源';
            }
          }
          return '房源 not found as visible text';
        })()
      \`,
      returnByValue: true
    }
  };
  ws.send(JSON.stringify(cmd));
});

ws.on('message', (data) => {
  const msg = JSON.parse(data);
  if (msg.id === 1) {
    console.log('Result:', JSON.stringify(msg.result));

    setTimeout(() => {
      const urlCmd = {
        id: 2,
        method: 'Runtime.evaluate',
        params: { expression: 'window.location.href', returnByValue: true }
      };
      ws.send(JSON.stringify(urlCmd));
    }, 3000);
  }
  if (msg.id === 2) {
    console.log('URL:', JSON.stringify(msg.result));

    // Get page content
    setTimeout(() => {
      const contentCmd = {
        id: 3,
        method: 'Runtime.evaluate',
        params: {
          expression: 'document.body.innerText',
          returnByValue: true
        }
      };
      ws.send(JSON.stringify(contentCmd));
    }, 2000);
  }
  if (msg.id === 3) {
    console.log('Page content:', JSON.stringify(msg.result).substring(0, 3000));
    ws.close();
  }
