# Let me look at the sidebar menu structure in detail
node -e "
const WebSocket = require('ws');
const ws = new WebSocket('ws://localhost:9222/devtools/page/ECB06F2BC4693849323A2A64BAD928C4');

ws.on('open', () => {
  const cmd = {
    id: 1,
    method: 'Runtime.evaluate',
    params: {
      expression: \`
        (function() {
          // Get sidebar menu items - find the aside or nav element
          const sidebars = document.querySelectorAll('.sidebar, .menu, aside, nav, .el-menu, [class*=menu], [class*=sidebar]');
          const results = [];
          for (const sb of sidebars) {
            const items = sb.querySelectorAll('a, [role=menuitem], .el-menu-item, li');
            for (const item of items) {
              const text = item.textContent.trim().substring(0, 30);
              const href = item.getAttribute('href') || '';
              const cls = item.className?.substring(0,40) || '';
              results.push({text, href, cls, tag: item.tagName});
            }
          }
          return JSON.stringify(results);
        })()
      \`,
      returnByValue: true
    }
  };
  ws.send(JSON.stringify(cmd));
});

ws.on('message', (data) => {
  const msg = JSON.parse(data);
  console.log('Sidebar items:', JSON.stringify(msg.result));
  ws.close();
});
